#!/usr/bin/env bun
/**
 * list.js - List all registered agents
 * 
 * This demonstrates that agents are NOT preloaded.
 * It only reads metadata from agent definition files.
 */

import { readdir, readFile } from 'fs/promises';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const AGENTS_DIR = join(__dirname, '..', 'agents');

async function listAgents() {
  try {
    const files = await readdir(AGENTS_DIR);
    const agentFiles = files.filter(f => f.endsWith('.json'));

    console.log('\n📦 Registered Agents (metadata only - NOT preloaded):');
    console.log('='.repeat(50));

