#!/usr/bin/env bun
/**
 * search.js - Search for agents matching a query
 * 
 * This is the first step in lazy agent discovery.
 * Searches agent metadata (name, description, tags) for relevance.
 * Does NOT load full agent instructions until get.js is called.
 */

import { readdir, readFile } from 'fs/promises';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const AGENTS_DIR = join(__dirname, '..', 'agents');

function calculateScore(agent, query) {
  let score = 0;
  const queryLower = query.toLowerCase();
  const keywords = queryLower.split(/\s+/).filter(k => k.length > 1);

  // Check name match (highest weight)
  if (agent.name.toLowerCase().includes(queryLower) || 
      keywords.some(k => agent.name.toLowerCase().includes(k))) {
    score += 0.4;
  }

  // Check description match
  if (agent.description.toLowerCase().includes(queryLower)) {
    score += 0.3;
  } else if (keywords.some(k => agent.description.toLowerCase().includes(k))) {
    score += 0.2;
  }

  // Check tags match
  const tagMatches = agent.tags.filter(t => 
    t.toLowerCase().includes(queryLower) || 
    keywords.some(k => t.toLowerCase().includes(k))
  );
  score += Math.min(tagMatches.length * 0.15, 0.3);

  return Math.min(score, 1.0);
}

async function searchAgents(query) {
  if (!query) {
    console.log('Usage: bun bin/search.js "<search query>"');
    console.log('Example: bun bin/search.js "code review security"');
    process.exit(1);
  }

  try {
    const files = await readdir(AGENTS_DIR);
    const agentFiles = files.filter(f => f.endsWith('.json'));

    const results = [];
    for (const file of agentFiles) {
      const content = await readFile(join(AGENTS_DIR, file), 'utf-8');
      const agent = JSON.parse(content);
      const score = calculateScore(agent, query);
      if (score > 0) {
        results.push({ ...agent, score });
      }
    }

    // Sort by score descending
    results.sort((a, b) => b.score - a.score);

    console.log('\n🔍 Search Results for: "' + query + '"');
    console.log('='.repeat(60));

    if (results.length === 0) {
      console.log('\nNo agents found matching your query.');
      console.log('Try: bun bin/list.js to see all available agents\n');
      return;
    }

    results.forEach((agent, idx) => {
      console.log(`\n${idx + 1}. ${agent.name} (score: ${agent.score.toFixed(2)})`);
      console.log(`   ${agent.description}`);
      console.log(`   Tags: ${agent.tags.join(', ')}`);
    });

    console.log('\n' + '='.repeat(60));
    console.log(`Found ${results.length} matching agent(s)`);
    console.log('\n💡 To load an agent, run:');
    if (results.length > 0) {
      console.log(`   bun bin/get.js ${results[0].name}`);
    }
    console.log('\n⚠️  Note: Agents are NOT preloaded - use get.js to load on demand!\n');

  } catch (error) {
    console.error('Error searching agents:', error.message);
    process.exit(1);
  }
}

const query = Bun.argv.slice(2).join(' ');
searchAgents(query);
EOF
