#!/usr/bin/env bun
/**
 * get.js - Load a specific agent by name
 * 
 * This implements lazy loading - the agent is only loaded when explicitly requested.
 * This is the second step after search.js in the discovery workflow.
 */

import { readFile } from 'fs/promises';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const AGENTS_DIR = join(__dirname, '..', 'agents');

async function getAgent(agentName) {
  if (!agentName) {
    console.log('Usage: bun bin/get.js <agent-name>');
    console.log('Example: bun bin/get.js code-reviewer');
    console.log('\nFirst, search for agents:');
    console.log('  bun bin/search.js "<query>"\n');
    process.exit(1);
  }

  try {
    const filePath = join(AGENTS_DIR, `${agentName}.json`);
    const content = await readFile(filePath, 'utf-8');
    const agent = JSON.parse(content);

    console.log('\n📥 Loading Agent (Lazy Load):');
    console.log('='.repeat(60));
    console.log(`\n🤖 Name: ${agent.name}`);
    console.log(`\n📝 Description: ${agent.description}`);
    console.log(`\n🏷️  Tags: ${agent.tags.join(', ')}`);
    console.log(`\n📋 Instructions:`);
    console.log('-'.repeat(40));
    console.log(agent.instructions);
    console.log('-'.repeat(40));
    console.log('\n' + '='.repeat(60));
    console.log('✅ Agent loaded successfully!');
    console.log('\n💡 This agent was just loaded on-demand.');
    console.log('   No other agents are loaded in memory.');
    console.log('   This is the lazy loading pattern in action.\n');

  } catch (error) {
    if (error.code === 'ENOENT') {
      console.log(`\n❌ Agent not found: ${agentName}`);
      console.log('\nAvailable agents:');
      console.log('  bun bin/list.js');
      console.log('\nSearch for agents:');
      console.log('  bun bin/search.js "<query>"\n');
    } else {
      console.error('Error loading agent:', error.message);
    }
    process.exit(1);
  }
}

const agentName = Bun.argv[2];
getAgent(agentName);
EOF
